package com.devteciot.dev_erp.Service;
import com.devteciot.dev_erp.DTO.DTOSetor.*; import com.devteciot.dev_erp.Exception.ResourceNotFoundException; import com.devteciot.dev_erp.Models.Setor; import com.devteciot.dev_erp.Repository.SetorRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class SetorService { private final SetorRepository r; public List<SetorGetDTO> listar(){return r.findByAtivoTrueOrderByNomeAsc().stream().map(this::dto).toList();} public SetorGetDTO buscar(Long id){return dto(r.findById(id).orElseThrow(()->new ResourceNotFoundException("Setor não encontrado: "+id)));} public SetorGetDTO criar(SetorPostDTO d){if(r.existsByNomeIgnoreCase(d.nome()))throw new IllegalArgumentException("Já existe um setor com esse nome."); Setor s=new Setor();s.setNome(d.nome().trim());return dto(r.save(s));} public SetorGetDTO atualizar(Long id,SetorPostDTO d){Setor s=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Setor não encontrado: "+id));if(!s.getNome().equalsIgnoreCase(d.nome())&&r.existsByNomeIgnoreCase(d.nome()))throw new IllegalArgumentException("Já existe um setor com esse nome.");s.setNome(d.nome().trim());return dto(r.save(s));} public void excluir(Long id){Setor s=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Setor não encontrado: "+id));s.setAtivo(false);r.save(s);} private SetorGetDTO dto(Setor s){return new SetorGetDTO(s.getId(),s.getNome(),s.getAtivo(),s.getDataCriacao(),s.getDataUpdate());}}
